def check_user_file_path(user_path):
    # Basic type and emptiness checks
    if not isinstance(user_path, str):
        return False
    user_path = user_path.strip()
    if not user_path:
        return False

    # Decode any percent-encoded characters to prevent bypasses
    try:
        decoded = unquote(user_path)
    except Exception:
        # In the unlikely event unquote fails, reject the path
        return False

    # Reject null bytes and control characters
    if any(ord(ch) < 32 for ch in decoded):
        return False

    # Enforce allowed character set
    if not valid_path_pattern.match(decoded):
        return False

    # Disallow absolute paths and trailing slashes
    if decoded.startswith('/'):
        return False
    if decoded.endswith('/'):
        return False

    # Enforce reasonable total length
    if len(decoded) > 1024:
        return False

    # Validate segments to prevent traversal and malformed paths
    segments = decoded.split('/')
    for seg in segments:
        # No empty segments (prevents double slashes)
        if seg == '':
            return False
        # No path traversal segments
        if seg in ('.', '..'):
            return False
        # Optional: enforce typical filename/segment length limits
        if len(seg) > 255:
            return False

    return True

