def generate_patient_summary(patient_id: str, report_template: str) -> str:
    """
    Generate a patient summary by filling the provided template with allowed patient information.

    Args:
        patient_id: Unique identifier of the patient.
        report_template: Template string that may include placeholders like {patient.name}.

    Returns:
        The template with placeholders replaced by the patient's information.

    Raises:
        ValueError: If the patient ID is invalid, or if the template attempts to access
                    restricted medical data, or references an unsupported field.
    """
    if patient_id not in patients_data:
        raise ValueError("Invalid patient ID.")

    patient = patients_data[patient_id]

    # Define allowed and restricted fields
    allowed_fields = {"id", "name", "age", "gender"}
    restricted_fields = {"diagnosis", "treatment_plan"}

    # Pattern to match placeholders like {patient.name}
    pattern = re.compile(r"\{patient\.([a-zA-Z_][a-zA-Z0-9_]*)\}")

    def replace_placeholder(match: re.Match) -> str:
        field = match.group(1)

        if field in restricted_fields:
