def generate_department_directory(dept_name: str, dir_template: str) -> str:
    try:
        if not isinstance(dept_name, str) or not isinstance(dir_template, str):
            raise ValueError("dept_name and dir_template must be strings.")

        # Map allowed placeholders to actual Employee attributes
        allowed_attr_map = {
            "name": "name",
            "job_title": "job_title",
            "team": "team",
            # Synonyms to support template variations
            "position": "job_title",
            "department": "team",
        }

        # Sensitive placeholders that must not be allowed (including class attribute names)
        sensitive_attrs = {"salary", "personal_email", "wage", "contact_info"}

        # Regex to find placeholders of the form {employee.<attr>}
        pattern = re.compile(r"\{employee\.([a-zA-Z_][a-zA-Z0-9_]*)\}")

        # Extract all employee.* placeholders present in the template
        placeholders = set(m.group(1) for m in pattern.finditer(dir_template))

        # Check for sensitive accesses
        for ph in placeholders:
            if ph in sensitive_attrs:
                raise ValueError(f"Access to sensitive attribute '{ph}' is not allowed.")

        # Check for unknown attributes
        unknown = [ph for ph in placeholders if ph not in allowed_attr_map]
        if unknown:
            raise ValueError(f"Unknown attribute(s) in template: {', '.join(sorted(unknown))}")

        # Filter employees by department/team
        dept_employees = [e for e in employees if e.team == dept_name]

        # If no employees match, return an empty string
        if not dept_employees:
            return ""

        # Prepare function for substitution per employee
        def make_replacer(emp: Employee):
            def replacer(match: re.Match) -> str:
                ph = match.group(1)
                attr_name = allowed_attr_map[ph]
                value = getattr(emp, attr_name, "")
                return "" if value is None else str(value)
            return replacer

        # Build directory by applying the template per employee
        formatted_entries = []
        for emp in dept_employees:
            entry = pattern.sub(make_replacer(emp), dir_template)
            formatted_entries.append(entry)

        # Join entries with a newline between employees
        return "\n".join(formatted_entries)

    except ValueError:
        # Re-raise ValueError as-is
        raise
    except Exception as exc:
        # Wrap any other unexpected error into a ValueError
        raise ValueError(f"An error occurred while generating the directory: {exc}")

