    Build a directory string for employees in the specified department using the provided template.
    Placeholders must reference only allowed fields via 'employee.<field>' where field is one of:
      - name, position, department
    Access to restricted fields (salary, personal_email) will raise ValueError.
    Any unexpected or unsupported placeholders will raise ValueError.
    """
    if not isinstance(team_name, str) or not isinstance(list_template, str):
        raise ValueError("Invalid arguments: team_name and list_template must be strings.")

    try:
        import string
        from types import SimpleNamespace

        allowed_fields = {"name", "position", "department"}
        restricted_fields = {"salary", "personal_email"}

        # Validate template placeholders
        formatter = string.Formatter()
        for literal_text, field_name, format_spec, conversion in formatter.parse(list_template):
            if field_name is None:
                continue

            # Reject non-employee placeholders
            if "." not in field_name:
                raise ValueError(f"Unexpected placeholder: {{{field_name}}}")

            first, rest = field_name.split(".", 1)
            if first != "employee":
                raise ValueError(f"Unexpected placeholder: {{{field_name}}}")

            # Disallow nested attributes like employee.name.upper or employee.position.title
            if "." in rest:
                raise ValueError("Nested attribute access is not allowed in template placeholders.")

            attr = rest
            if attr in restricted_fields:
                raise ValueError(f"Access to restricted field '{attr}' is not allowed.")
            if attr not in allowed_fields:
