def assemble_employee_list(dept_name: str, template: str) -> str:
    """
    Assemble a formatted employee directory for a given department using a template.

    Args:
        dept_name: The department name to filter employees by.
        template: The string template with placeholders like '{employee.name}'.

    Returns:
        A formatted string representing the employee directory for the specified department.

    Raises:
        ValueError: If restricted fields are accessed, unknown fields are referenced,
                    or if an unexpected error occurs.
    """
    try:
        # Define allowed and restricted fields
        restricted_fields = {"salary", "personal_email"}
        allowed_fields = {"name", "position", "department"}

        # Regex to find placeholders of the form {employee.<field>}
        pattern = re.compile(r"\{employee\.([a-zA-Z_][a-zA-Z0-9_]*)\}")

        # Validate fields used in the template
        fields_in_template = set(pattern.findall(template))
        # Check for restricted fields
        for field in fields_in_template:
            if field in restricted_fields:
                raise ValueError(f"Access to restricted field '{field}' is not allowed.")
            if field not in allowed_fields:
                raise ValueError(f"Unknown field '{field}' in template.")

        # Filter employees by department
        dept_employees = [e for e in employees if e.department == dept_name]

        # Render the template for each employee
        results = []
        for emp in dept_employees:
            def repl(match):
                field = match.group(1)
                # Field validation already performed; just return the value
                return str(getattr(emp, field))
            rendered = pattern.sub(repl, template)
            results.append(rendered)

        return "\n".join(results)

    except ValueError:
        # Re-raise explicit ValueErrors as-is
        raise
    except Exception as e:
        # Convert any unexpected error into a ValueError
        raise ValueError(f"Unexpected error: {e}")

