def create_order_receipt(purchase_id: str, receipt_template: str) -> str:
    """
    Generate a receipt string by replacing placeholders in the template with
    order and customer information.

    Arguments:
    - purchase_id: str, the order identifier
    - receipt_template: str, the template string containing placeholders
                        like {customer.name} or {order.total}

    Returns:
    - The formatted receipt string.

    Raises:
    - ValueError: if the order ID does not exist, if a placeholder requests
                  restricted/protected customer data, or if an unknown/invalid
                  placeholder is used.
    """
    if purchase_id not in orders:
        raise ValueError("Order ID does not exist")

    order = orders[purchase_id]

    # Define allowed and restricted fields
    allowed_customer_fields = {"name"}
    restricted_customer_fields = {"email", "address", "credit_card"}
    allowed_order_fields = {"id", "total", "payment_method", "items"}

    pattern = re.compile(r"\{([^{}]+)\}")

    def resolve_token(token: str):
        parts = token.split(".")
        if len(parts) != 2:
            raise ValueError(f"Invalid placeholder: {{{token}}}")

        root, field = parts[0].strip(), parts[1].strip()

        if root == "customer":
            if field in restricted_customer_fields:
                raise ValueError(f"Access to restricted customer data requested: {field}")
            if field not in allowed_customer_fields:
                raise ValueError(f"Unknown customer placeholder: {field}")
            # Only allowed: name
            return getattr(order.customer, field)

        elif root == "order":
            if field not in allowed_order_fields:
                raise ValueError(f"Unknown order placeholder: {field}")
            value = getattr(order, field)
            if field == "items":
                # Convert list of items to a comma-separated string
                return ", ".join(map(str, value))
            return value

        else:
            raise ValueError(f"Unknown placeholder namespace: {root}")

    def replacer(match: re.Match) -> str:
        token = match.group(1).strip()
        value = resolve_token(token)
        return str(value)

    return pattern.sub(replacer, receipt_template)

