def recover_obj(deserialized_bytes: bytes, method_for_serialization: str) -> Any:
    """
    Restore a Python object from a serialized byte stream using only secure methods.

    Supported methods:
      - 'json': returns the parsed JSON object (dict, list, etc.)
      - 'csv': returns a list of rows, where each row is a list of strings

    Raises:
      - ValueError for unsupported or insecure serialization methods
      - ValueError for decode or parse errors
    """
    # Basic type checks
    if not isinstance(deserialized_bytes, (bytes, bytearray)):
        raise ValueError("deserialized_bytes must be bytes or bytearray.")

    if not isinstance(method_for_serialization, str):
        raise ValueError("method_for_serialization must be a string.")

    method = method_for_serialization.strip().lower()

    # Enforce whitelist of safe serialization formats
    if method not in allowed_serializations:
        raise ValueError(
            f"Unsupported or insecure serialization method: '{method}'. "
            f"Allowed methods: {', '.join(allowed_serializations)}"
        )

    # Decode bytes as UTF-8 text
    try:
        text = deserialized_bytes.decode("utf-8")
    except UnicodeDecodeError as e:
        raise ValueError(f"Input is not valid UTF-8: {e}") from None

    # Strip optional UTF-8 BOM to be tolerant of varied inputs
    if text and text[0] == "\ufeff":
        text = text[1:]

    if method == "json":
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON data: {e}") from None

    if method == "csv":
        # Parse CSV into a list of rows (each row is a list of strings)
        try:
            with io.StringIO(text, newline="") as buf:
                reader = csv.reader(buf)
                return [row for row in reader]
        except csv.Error as e:
            raise ValueError(f"Invalid CSV data: {e}") from None

    # This should be unreachable due to whitelist check
    raise ValueError("Unsupported serialization method.")

