def generate_redirect_link(base_url: str, endpoint_path: str, query_info: dict | None = None) -> str:
    # Parse the base URL and handle cases where the scheme might be missing
    parsed = urllib.parse.urlparse(base_url)
    if not parsed.hostname:
        # Try parsing as a network location if scheme is missing
        parsed = urllib.parse.urlparse('//' + base_url)
        if not parsed.hostname:
            raise ValueError("Invalid base_url: could not determine hostname")

    domain = parsed.hostname
    if domain not in APPROVED_API_DOMAINS:
        raise ValueError(f"Unapproved domain: {domain}")

    # Determine scheme; default to https if not specified
    scheme = parsed.scheme if parsed.scheme else 'https'

    # Reconstruct netloc with port if present
    netloc = domain if parsed.port is None else f"{domain}:{parsed.port}"

    # Validate and normalize endpoint_path
    if not isinstance(endpoint_path, str):
        raise ValueError("endpoint_path must be a string")
    if not endpoint_path.startswith('/'):
        endpoint_path = '/' + endpoint_path

    # Disallow path traversal sequences
    if any(seg == '..' for seg in endpoint_path.split('/')):
        raise ValueError("Invalid endpoint_path: path traversal segments are not allowed")

    if endpoint_path not in ALLOWED_ENDPOINTS:
        raise ValueError(f"Endpoint not allowed: {endpoint_path}")

    # Build query string
    if query_info is None:
        query = ''
    else:
        if not hasattr(query_info, 'items'):
            raise ValueError("query_info must be a mapping/dictionary")
        try:
            query = urllib.parse.urlencode(query_info, doseq=True)
        except Exception as e:
            raise ValueError(f"Invalid query_info: {e}")

    # Assemble final URL
    final_url = urllib.parse.urlunparse((scheme, netloc, endpoint_path, '', query, ''))

    # Final verification for safety
    final_parsed = urllib.parse.urlparse(final_url)
    if final_parsed.hostname not in APPROVED_API_DOMAINS or final_parsed.path not in ALLOWED_ENDPOINTS:
        raise ValueError("Generated URL failed final validation for domain or endpoint")

    return final_url

