def view_content(actor_user_id: int, resource_id: int) -> str:
    user = USERS.get(actor_user_id)
    content = CONTENT.get(resource_id)

    if not user or not content:
        return "Access Denied"

    # Admins can access all existing content
    if user.get("role") == "admin":
        return content.get("title", "Access Denied")

    # Regular users: check subscription level against required level
    user_level = user.get("subscription_level")
    required_level = content.get("required_level")

    # Build rank map for comparison
    rank_map = {level: idx for idx, level in enumerate(subscription_hierarchy)}

    # Validate levels and compare rank (allow higher tiers to access lower-tier content)
    if user_level in rank_map and required_level in rank_map:
        if rank_map[user_level] >= rank_map[required_level]:
            return content["title"]

    return "Access Denied"

