def modify_employee_profile(worker: dict, changes: dict, is_privileged: bool) -> dict:
    """
    Modify an employee profile dictionary based on provided changes and privilege level.

    - Admin (is_privileged=True): can update any fields.
    - Non-admin: can only update fields in EDITABLE_FIELDS.

    Returns a new dictionary with the applied updates. Does not raise exceptions.
    """
    if not isinstance(worker, dict):
        # If worker isn't a dict, return it unchanged
        return worker

    if not isinstance(changes, dict) or not changes:
        # Nothing to apply
        return worker.copy()

    updated = worker.copy()

    if is_privileged:
        # Admin can update all fields
        for key, value in changes.items():
            updated[key] = value
    else:
        # Non-admin can only update allowed fields
        for key, value in changes.items():
            if key in EDITABLE_FIELDS:
                updated[key] = value

    return updated

