def calculate_expression(expr_string: str):
    """
    Safely evaluate a basic arithmetic expression from a string using AST parsing.
    Allowed operations: +, -, *, /, **, unary +/-, and parentheses.
    Numeric literals may be integers or floats (including scientific notation).
    Raises ValueError for any illegal constructs or evaluation errors.
    """
    if not isinstance(expr_string, str):
        raise ValueError("Expression must be a string.")
    s = expr_string.strip()
    if not s:
        raise ValueError("Empty expression.")

    # Parse expression into AST
    try:
        tree = ast.parse(s, mode='eval')
    except Exception as e:
        raise ValueError("Invalid expression syntax.") from e

    def eval_node(node):
        # Expression root
        if isinstance(node, ast.Expression):
            return eval_node(node.body)

        # Binary operations
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op = node.op
            try:
                if isinstance(op, ast.Add):
                    return left + right
                elif isinstance(op, ast.Sub):
                    return left - right
                elif isinstance(op, ast.Mult):
                    return left * right
                elif isinstance(op, ast.Div):
                    return left / right
                elif isinstance(op, ast.Pow):
                    return left ** right
                else:
                    raise ValueError("Unsupported binary operator.")
            except Exception as e:
                raise ValueError(f"Evaluation error: {e}") from e

        # Unary operations (+ / -)
        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +operand
            elif isinstance(node.op, ast.USub):
                return -operand
            else:
                raise ValueError("Unsupported unary operator.")

        # Numeric literals (int / float). Disallow bools and other types.
        if isinstance(node, ast.Constant):
            val = node.value
            if isinstance(val, bool):
                raise ValueError("Boolean values are not allowed.")
            if isinstance(val, (int, float)):
                return val
            raise ValueError("Only numeric literals are allowed.")
        # For compatibility with older Python versions:
        if hasattr(ast, "Num") and isinstance(node, ast.Num):
            val = node.n
            if isinstance(val, (int, float)):
                return val
            raise ValueError("Only numeric literals are allowed.")

        # Explicitly disallow any potentially unsafe or unintended nodes
        if isinstance(node, (ast.Call, ast.Name, ast.Attribute, ast.Subscript,
                             ast.Dict, ast.List, ast.Tuple, ast.Set,
                             ast.Compare, ast.BoolOp, ast.IfExp, ast.Lambda,
                             ast.Assign, ast.AugAssign, ast.For, ast.While,
                             ast.With, ast.Import, ast.ImportFrom, ast.FunctionDef,
                             ast.ClassDef)):
            raise ValueError(f"Illegal or unsafe expression element: {type(node).__name__}")

        # Catch-all for anything else not explicitly handled
        raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    try:
        result = eval_node(tree)
    except ValueError:
        # Already a ValueError with useful message
        raise
    except Exception as e:
        # Any other runtime error is wrapped as ValueError
        raise ValueError(f"Evaluation failed: {e}") from e

    # Ensure the result is numeric
    if not isinstance(result, (int, float)):
        raise ValueError("Expression did not produce a numeric result.")

    return result

