def securely_compute_expression(formula: str) -> str:
    """
    Safely compute a minimal arithmetic/logic expression from a user-supplied string.
    Returns the stringified result on success, otherwise 'Processing Failed!'.
    """

    # Safety limits
    MAX_INPUT_LENGTH = 256
    MAX_AST_DEPTH = 50
    MAX_INT_ABS = 10**18
    MAX_FLOAT_ABS = 1e18
    MAX_POWER_EXPONENT_ABS = 10
    MAX_RESULT_STR_LEN = 2048

    def _is_number(x: Any) -> bool:
        return (isinstance(x, (int, float))) and not isinstance(x, bool)

    def _is_bool(x: Any) -> bool:
        return isinstance(x, bool)

    def _check_magnitude(x: Any) -> None:
        if _is_number(x):
            if isinstance(x, int):
                if abs(x) > MAX_INT_ABS:
                    raise ValueError("Result too large")
            else:
                if abs(x) > MAX_FLOAT_ABS:
                    raise ValueError("Result too large")

    def _safe_bool_and(values):
        # Short-circuit AND
        result = True
        for v in values:
            if not _is_bool(v):
                raise TypeError("AND requires booleans")
            result = result and v
            if not result:  # short-circuit
                break
        return result

    def _safe_bool_or(values):
        # Short-circuit OR
        result = False
        for v in values:
            if not _is_bool(v):
                raise TypeError("OR requires booleans")
            result = result or v
            if result:  # short-circuit
                break
        return result

    def _eval(node: ast.AST, depth: int = 0) -> Any:
        if depth > MAX_AST_DEPTH:
            raise ValueError("Expression too complex")

        if isinstance(node, ast.Expression):
            return _eval(node.body, depth + 1)

        # Constants
        if isinstance(node, ast.Constant):
            val = node.value
            if _is_number(val) or _is_bool(val):
                return val
            # Disallow other constant types (str, bytes, None, complex, etc.)
            raise TypeError("Unsupported constant type")

        # (For older Python versions)
        if hasattr(ast, "NameConstant") and isinstance(node, ast.NameConstant):
            val = node.value
            if _is_bool(val):
                return val
            raise TypeError("Unsupported name constant type")

        # Unary operations: +x, -x, not x
        if isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand, depth + 1)

            if isinstance(node.op, ast.UAdd):
                if not _is_number(operand):
                    raise TypeError("Unary plus requires a number")
                _check_magnitude(operand)
                return +operand

            if isinstance(node.op, ast.USub):
                if not _is_number(operand):
                    raise TypeError("Unary minus requires a number")
                res = -operand
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Not):
                if not _is_bool(operand):
                    raise TypeError("not requires a boolean")
                return not operand

            raise TypeError("Unsupported unary operation")

        # Binary operations: +, -, *, /, //, %, **
        if isinstance(node, ast.BinOp):
            left = _eval(node.left, depth + 1)
            right = _eval(node.right, depth + 1)

            if isinstance(node.op, ast.Add):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Addition requires numbers")
                res = left + right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Sub):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Subtraction requires numbers")
                res = left - right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Mult):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Multiplication requires numbers")
                res = left * right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Div):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Division requires numbers")
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                res = left / right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.FloorDiv):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Floor division requires numbers")
                if right == 0:
                    raise ZeroDivisionError("floor division by zero")
                res = left // right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Mod):
                if not (_is_number(left) and _is_number(right)):
                    raise TypeError("Modulo requires numbers")
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                res = left % right
                _check_magnitude(res)
                return res

            if isinstance(node.op, ast.Pow):
                if not (_is_number(left) and isinstance(right, int)):
                    # Restrict exponent to integer for predictability and safety
                    raise TypeError("Power requires number ** integer exponent")
                if abs(right) > MAX_POWER_EXPONENT_ABS:
                    raise ValueError("Exponent too large")
                # Also restrict base magnitude to avoid huge results
                if _is_number(left) and abs(left) > MAX_INT_ABS:
                    raise ValueError("Base too large for exponentiation")
                res = left ** right
                _check_magnitude(res)
                return res

            # Disallow bitwise and other binary operations
            raise TypeError("Unsupported binary operation")

        # Boolean operations: and/or (on booleans only)
        if isinstance(node, ast.BoolOp):
            # Evaluate values respecting short-circuit semantics
            values = []
            # For short-circuit, evaluate incrementally
            if isinstance(node.op, ast.And):
                for v_node in node.values:
                    v_val = _eval(v_node, depth + 1)
                    if not _is_bool(v_val):
                        raise TypeError("AND requires booleans")
                    values.append(v_val)
                    if v_val is False:
                        break
                return _safe_bool_and(values)
            elif isinstance(node.op, ast.Or):
                for v_node in node.values:
                    v_val = _eval(v_node, depth + 1)
                    if not _is_bool(v_val):
                        raise TypeError("OR requires booleans")
                    values.append(v_val)
                    if v_val is True:
                        break
                return _safe_bool_or(values)
            else:
                raise TypeError("Unsupported boolean operation")

        # Comparisons: < <= > >= == != (numbers or booleans)
        if isinstance(node, ast.Compare):
            left_val = _eval(node.left, depth + 1)
            comps = []
            for op, comparator in zip(node.ops, node.comparators):
                right_val = _eval(comparator, depth + 1)

                # Only allow comparisons either between numbers or between booleans
                if (_is_number(left_val) and _is_number(right_val)) or (_is_bool(left_val) and _is_bool(right_val)):
                    if isinstance(op, ast.Lt):
                        comps.append(left_val < right_val)
                    elif isinstance(op, ast.LtE):
                        comps.append(left_val <= right_val)
                    elif isinstance(op, ast.Gt):
                        comps.append(left_val > right_val)
                    elif isinstance(op, ast.GtE):
                        comps.append(left_val >= right_val)
                    elif isinstance(op, ast.Eq):
                        comps.append(left_val == right_val)
                    elif isinstance(op, ast.NotEq):
                        comps.append(left_val != right_val)
                    else:
                        raise TypeError("Unsupported comparison operator")
                else:
                    raise TypeError("Unsupported comparison between given types")

                # Chain comparison semantics
                left_val = right_val

            return all(comps)

        # Parentheses and grouping are handled implicitly by the AST structure.
        # Disallow names, calls, attributes, subscripts, lambdas, comprehensions, etc.
        disallowed = (
            ast.Name, ast.Call, ast.Attribute, ast.Subscript, ast.Dict, ast.List, ast.Tuple,
            ast.Lambda, ast.IfExp, ast.Set, ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp,
            ast.Await, ast.Yield, ast.YieldFrom, ast.FormattedValue, ast.JoinedStr
        )
        if isinstance(node, disallowed):
            raise TypeError("Unsupported or unsafe construct")

        # Any other node is unsafe
        raise TypeError("Unsupported expression element")

    try:
        if not isinstance(formula, str):
            return "Processing Failed!"
        src = formula.strip()
        if not src:
            return "Processing Failed!"
        if len(src) > MAX_INPUT_LENGTH:
            return "Processing Failed!"

        # Parse as a single expression
