    """
    Safely evaluate a basic arithmetic expression in Python syntax.
    Allowed:
      - Numbers (int, float; scientific notation allowed)
      - Parentheses
      - Unary + and -
      - Binary operators: +, -, *, /, //, %, **

    Returns:
      - String representation of the result
      - 'Computation Error!' on any failure or unsafe input
    """
    try:
        if not isinstance(expr_input, str):
            return 'Computation Error!'

        # Limit input size to mitigate abuse
        if len(expr_input) > 1000:
            return 'Computation Error!'

        # Parse the expression
        try:
            tree = ast.parse(expr_input, mode='eval')
        except Exception:
            return 'Computation Error!'

        def eval_node(node: ast.AST) -> Union[int, float]:
            # Expression root
            if isinstance(node, ast.Expression):
                return eval_node(node.body)

            # Numeric constants (int, float only)
            if isinstance(node, ast.Constant):
                val = node.value
                if isinstance(val, (int, float)):
                    return val
                # Disallow complex or other constant types
                raise ValueError('unsupported constant')

            # Unary operations: +x, -x
            if isinstance(node, ast.UnaryOp):
                operand = eval_node(node.operand)
                if not isinstance(operand, (int, float)):
                    raise ValueError('unsupported operand')
                if isinstance(node.op, ast.UAdd):
                    return +operand
                if isinstance(node.op, ast.USub):
                    return -operand
                raise ValueError('unsupported unary op')

            # Binary operations
            if isinstance(node, ast.BinOp):
                left = eval_node(node.left)
                right = eval_node(node.right)
                if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
                    raise ValueError('unsupported operand types')

                if isinstance(node.op, ast.Add):
                    return left + right
                if isinstance(node.op, ast.Sub):
                    return left - right
                if isinstance(node.op, ast.Mult):
                    return left * right
                if isinstance(node.op, ast.Div):
                    return left / right
                if isinstance(node.op, ast.FloorDiv):
                    return left // right
                if isinstance(node.op, ast.Mod):
                    return left % right
                if isinstance(node.op, ast.Pow):
                    # Guard against excessively large exponents
                    if isinstance(right, int):
                        if abs(right) > 2000:
                            raise ValueError('unsafe exponent')
                    elif isinstance(right, float):
                        if abs(right) > 1000:
                            raise ValueError('unsafe exponent')
                    return left ** right

                raise ValueError('unsupported binary op')

            # Any other node types are unsafe/suspicious
            raise ValueError('unsafe or unsupported node')

        # Evaluate safely
        result = eval_node(tree)

        # Reject non-finite float results
        if isinstance(result, float) and not math.isfinite(result):
            return 'Computation Error!'

        return str(result)

    except Exception:
