    Formats the given string using only the allowed placeholder:
    {userinfo.user_name}

    Any other field, conversion, or format specifier will raise ValueError.
    """
    try:
        if not isinstance(string, str):
            raise ValueError("Input must be a string.")

        # Validate the format string strictly
        fmt = Formatter()
        for literal_text, field_name, format_spec, conversion in fmt.parse(string):
